package com.gaiys.proto.system.security.encoder;

import java.nio.charset.StandardCharsets;
import java.security.GeneralSecurityException;
import java.util.Base64;
import javax.crypto.SecretKeyFactory;
import javax.crypto.spec.PBEKeySpec;
import org.hswebframework.web.system.authorization.api.PasswordEncoder;

/** Uses the random salt generated by hsweb; no plaintext or reversible passwords. */
public final class StrongPasswordEncoder implements PasswordEncoder {
    public static final int ITERATIONS = 600_000;

    @Override
    public String encode(String password, String salt) {
        if (password == null || salt == null || salt.length() < 16) {
            throw new IllegalArgumentException("validation.password_invalid");
        }
        PBEKeySpec spec =
                new PBEKeySpec(
                        password.toCharArray(),
                        salt.getBytes(StandardCharsets.UTF_8),
                        ITERATIONS,
                        256);
        try {
            byte[] hash =
                    SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256")
                            .generateSecret(spec)
                            .getEncoded();
            return "pbkdf2-sha256$" + ITERATIONS + "$" + Base64.getEncoder().encodeToString(hash);
        } catch (GeneralSecurityException error) {
            throw new IllegalStateException("PBKDF2 unavailable", error);
        } finally {
            spec.clearPassword();
        }
    }
}
